const html = "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <title>K3的梦想单预测</title>\n  <style>:root{--bg:#eef4f1;--ink:#10201b;--muted:#61726c;--line:#d8e5de;--green:#12a56f;--gold:#e0b44c;--red:#c95449;--blue:#28699f;--panel:#f7fbf8;--shadow:0 20px 45px rgba(0,0,0,.14)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;color:var(--ink);background:var(--bg)}button,input,select{font:inherit}.intro{position:fixed;inset:0;z-index:100;display:grid;place-items:center;text-align:center;padding:24px;color:#fff;background:radial-gradient(circle at 50% 38%,rgba(18,165,111,.34),transparent 22%),linear-gradient(145deg,#06130e,#0b281d 55%,#06130e);transition:opacity .5s ease,visibility .5s ease}.intro.hide{opacity:0;visibility:hidden}.intro h1{max-width:900px;margin:18px 0 10px;font-size:clamp(38px,8vw,86px);line-height:1;letter-spacing:0}.intro p{margin:0 0 24px;color:#cfe4dc}.intro button,.primary,.ghost,.mini,.account-btn,.paywall button,.activate{min-height:42px;border:0;border-radius:7px;padding:0 16px;font-weight:850;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;cursor:pointer}.intro button,.primary,.paywall button,.activate{color:#092017;background:linear-gradient(135deg,var(--gold),#ffe09a)}.ghost,.account-btn{border:1px solid rgba(255,255,255,.34);color:#fff;background:rgba(255,255,255,.12)}.mini{color:var(--ink);border:1px solid var(--line);background:#fff}.intro-orbit{position:relative;width:148px;height:148px;border:1px solid rgba(255,255,255,.24);border-radius:50%;animation:spin 7s linear infinite}.intro-orbit span{position:absolute;width:18px;height:18px;border-radius:50%;background:var(--gold);box-shadow:0 0 24px rgba(224,180,76,.9)}.intro-orbit span:nth-child(1){top:-9px;left:64px}.intro-orbit span:nth-child(2){right:12px;bottom:18px;background:var(--green)}.intro-orbit span:nth-child(3){left:8px;bottom:24px;background:var(--blue)}@keyframes spin{to{transform:rotate(360deg)}}.topbar{position:sticky;top:0;z-index:30;display:flex;justify-content:space-between;align-items:center;gap:18px;padding:14px clamp(16px,4vw,36px);border-bottom:1px solid rgba(255,255,255,.12);color:#fff;background:rgba(7,20,15,.92);backdrop-filter:blur(14px)}.brand{display:flex;align-items:center;gap:12px}.brand b{display:block}.brand small{color:#b8cbc4;font-size:12px}.logo{width:42px;height:42px;display:grid;place-items:center;border-radius:50%;font-weight:950;color:#092017;background:conic-gradient(from 20deg,var(--gold),#fff2b8,var(--green),var(--gold));box-shadow:0 0 0 3px rgba(255,255,255,.1)}nav{display:flex;align-items:center;gap:8px}nav a{color:#dbece6;text-decoration:none;padding:9px 10px;border-radius:6px}nav a:hover{background:rgba(255,255,255,.1)}main{max-width:1440px;margin:0 auto;padding:20px clamp(14px,3vw,30px) 44px}.hero{min-height:480px;display:grid;grid-template-columns:minmax(0,1fr) 330px;align-items:end;gap:28px;margin-bottom:18px;padding:clamp(26px,5vw,58px);border-radius:10px;color:#fff;background:linear-gradient(105deg,rgba(5,18,13,.94),rgba(5,18,13,.65),rgba(5,18,13,.25)),url(\"https://images.unsplash.com/photo-1574629810360-7efbbe195018?auto=format&fit=crop&w=1800&q=80\") center/cover;box-shadow:var(--shadow)}.eyebrow{margin:0 0 10px;color:#cfe7de;font-size:13px;font-weight:900;text-transform:uppercase}.dark{color:var(--green)}h1,h2,h3,p{margin-top:0}h1{max-width:860px;margin-bottom:14px;font-size:clamp(38px,6vw,76px);line-height:1.01}.lead{max-width:760px;color:#e5f1ec;line-height:1.75}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:24px}.hero-card{display:grid;gap:8px;padding:20px;border:1px solid rgba(255,255,255,.26);border-radius:8px;background:rgba(255,255,255,.14);backdrop-filter:blur(14px)}.hero-card span{color:#cfe7de}.hero-card strong{font-size:30px}.hero-card p{margin:0;color:#e5f1ec;line-height:1.55}.panel{padding:18px;border:1px solid var(--line);border-radius:8px;background:var(--panel);box-shadow:0 16px 34px rgba(16,32,27,.07)}.section-head{display:flex;justify-content:space-between;gap:18px;align-items:start;margin-bottom:14px}.section-head h2{margin-bottom:0}.section-head p{max-width:560px;margin-bottom:0;color:var(--muted);font-size:13px;line-height:1.55}.live-panel{margin-bottom:18px}iframe{width:100%;height:520px;border:1px solid var(--line);border-radius:8px;background:#fff}.iframe-note{margin-top:10px;color:var(--muted);font-size:13px}.layout{display:grid;grid-template-columns:330px minmax(0,1fr);gap:18px}.side,.desk{display:grid;gap:14px;align-content:start}label{display:grid;gap:7px;color:var(--muted);font-size:12px;font-weight:760}input,select{width:100%;min-height:42px;border:1px solid var(--line);border-radius:6px;padding:0 11px;color:var(--ink);background:#fff}.paywall{grid-column:1/-1;display:none;align-items:center;justify-content:space-between;gap:14px;padding:16px;border:1px solid #ecd59a;border-radius:8px;background:#fff7df;box-shadow:0 12px 28px rgba(16,32,27,.08)}.locked .paywall{display:flex}.paywall b{display:block}.paywall span{display:block;color:var(--muted);font-size:13px}.locked .desk{filter:blur(2px);pointer-events:none;user-select:none}.match-list{display:grid;gap:10px}.match{width:100%;display:grid;gap:6px;padding:13px;border:1px solid var(--line);border-radius:8px;text-align:left;color:var(--ink);background:#fff;cursor:pointer}.match.active{border-color:rgba(18,165,111,.5);box-shadow:inset 4px 0 0 var(--green),0 12px 24px rgba(16,32,27,.08)}.match span{color:var(--muted);font-size:12px}.match-hero h2{font-size:34px;margin-bottom:8px}.result-strip{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:16px}.result-strip div,.prob div,.metric{padding:14px;border:1px solid var(--line);border-radius:8px;background:#fff}.result-strip span,.prob span,.metric span{display:block;margin-bottom:6px;color:var(--muted);font-size:12px}.grid{display:grid;gap:16px}.two{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.prob{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:14px}.prob b{font-size:26px}.scores{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px}.score{padding:10px;border-radius:7px;background:#eef6f2}.score b{display:block}.score span{color:var(--muted);font-size:12px}.odds{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.note{margin-top:14px;padding:12px;border-radius:8px;color:#20342e;background:#eef6f2;line-height:1.55}.compare{display:grid;grid-template-columns:1fr 1fr;gap:14px}.team{display:grid;gap:10px}.team header{display:flex;justify-content:space-between;gap:10px}.badge{width:42px;height:42px;display:grid;place-items:center;border-radius:50%;color:#fff;font-weight:900;background:linear-gradient(135deg,var(--blue),var(--green))}.bar{display:grid;grid-template-columns:64px 1fr 34px;gap:8px;align-items:center;color:var(--muted);font-size:12px}.track{height:8px;border-radius:999px;background:#e4ede8;overflow:hidden}.fill{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,var(--green),var(--gold))}.bullets{margin:0;padding-left:18px;color:var(--muted);line-height:1.65}.advance{display:grid;gap:10px}.metric strong{font-size:18px}.reason,.ai-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.ai-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.reason-card,.ai-card{padding:13px;border:1px solid var(--line);border-radius:8px;background:#fff}.reason-card h3,.ai-card h3{margin-bottom:6px}.reason-card p,.ai-card p{margin-bottom:0;color:var(--muted);font-size:13px;line-height:1.55}.ai-card h3{display:flex;align-items:center;justify-content:space-between;gap:10px}.ai-card em{font-style:normal;font-size:11px;color:#fff;background:var(--green);border-radius:999px;padding:3px 8px}.ai-card.pending em{background:#8a9892}.ai-card strong{display:block;margin:8px 0;font-size:20px}.auth-dialog{width:min(520px,calc(100vw - 28px));border:0;border-radius:10px;padding:0;box-shadow:0 30px 80px rgba(0,0,0,.34)}.auth-dialog::backdrop{background:rgba(5,18,13,.62);backdrop-filter:blur(4px)}.auth-box{position:relative;display:grid;gap:14px;padding:22px;background:#f7fbf8}.auth-box h2{margin-bottom:0}.auth-box p{margin-bottom:0;color:var(--muted);line-height:1.55}.close{position:absolute;right:12px;top:10px;width:34px;height:34px;border:0;border-radius:50%;background:#e9f1ed;font-size:22px;cursor:pointer}.pay-card{display:grid;gap:4px;padding:16px;border:1px solid var(--line);border-radius:8px;background:#fff}.pay-card span,.pay-card small{color:var(--muted)}.pay-card b{font-size:32px}.alipay-box{display:grid;place-items:center;min-height:150px;border:1px dashed #9eb3aa;border-radius:8px;color:var(--muted);background:#fff}.auth-hint{min-height:20px;color:var(--red);font-size:13px}.auth-hint.ok{color:var(--green)}footer{padding:26px;text-align:center;color:#64756e}@media(max-width:1080px){.hero,.layout,.two,.reason,.ai-grid{grid-template-columns:1fr}}@media(max-width:720px){.topbar,.section-head,.compare{align-items:stretch;flex-direction:column;grid-template-columns:1fr}nav{overflow-x:auto}.prob,.odds,.scores,.result-strip{grid-template-columns:1fr 1fr}iframe{height:420px}h1{font-size:38px}.paywall{align-items:stretch;flex-direction:column}.account-btn{white-space:nowrap}}.lab-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.lab-card{padding:14px;border:1px solid var(--line);border-radius:8px;background:#fff}.lab-card h3{margin-bottom:10px}.kelly-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.kelly-cell{padding:11px;border-radius:7px;background:#eef6f2}.kelly-cell span{display:block;color:var(--muted);font-size:12px}.kelly-cell b{font-size:18px}.small-actions{margin:0 0 10px}.danger{color:#fff!important;background:var(--red)!important;border-color:var(--red)!important}.history{margin-top:14px;display:grid;gap:8px}.history-row{display:grid;grid-template-columns:140px 1fr 1fr 1fr;gap:8px;padding:10px;border:1px solid var(--line);border-radius:7px;background:#fff;color:var(--muted);font-size:12px}.history-row b{color:var(--ink)}@media(max-width:900px){.lab-grid,.kelly-grid,.history-row{grid-template-columns:1fr}}.monitor-alert{margin-top:10px;padding:10px;border-radius:7px;background:#fff1e8;color:#8a3b1b;font-size:13px}.training-good{color:var(--green);font-weight:850}.training-warn{color:var(--red);font-weight:850}\n.schedule-status{border:1px solid rgba(16,32,27,.12);border-radius:8px;padding:10px 12px;margin-bottom:10px;font-size:12px;line-height:1.5;color:#406058;background:#f7fbf8}.schedule-status.ok{border-color:rgba(18,165,111,.35);color:#0d6e4b}.schedule-status.warn{border-color:rgba(224,180,76,.55);color:#7a5a11;background:#fff8e9}.alipay-box img{max-width:220px;width:100%;height:auto;border-radius:8px;display:block}\r\n.admin-tools{border:1px solid var(--line);border-radius:8px;padding:10px 12px;background:#fff}.admin-tools summary{cursor:pointer;font-weight:850;color:var(--ink);margin-bottom:8px}.admin-tools[open]{display:grid;gap:10px}.admin-tools .mini{width:100%}\r\n</style>\n</head>\n<body>\n  <div id=\"intro\" class=\"intro\">\n    <div class=\"intro-orbit\"><span></span><span></span><span></span></div>\n    <h1>欢迎使用K3的梦想单预测</h1>\n    <p>实时赔率 · 手机号开通 · AI多模型 · 泊松比分</p>\n    <button id=\"skipIntro\">进入预测台</button>\n  </div>\n\n  <header class=\"topbar\">\n    <div class=\"brand\"><span class=\"logo\">K3</span><div><b>K3的梦想单预测</b><small>世界杯赛程分析与赔率计算</small></div></div>\n    <nav>\n      <a href=\"#odds\">实时赔率</a>\n      <a href=\"#predict\">单场预测</a>\n      <a href=\"#aiModels\">AI多模型</a><a href=\"#strategyLab\">策略实验室</a>\n      <button id=\"accountBtn\" class=\"account-btn\">登录/充值</button>\n    </nav>\n  </header>\n\n  <main>\n    <section class=\"hero\">\n      <div>\n        <p class=\"eyebrow\">Dream Ticket Forecast</p>\n        <h1>把赔率、阵容和赛程压力放到同一个预测台</h1>\n        <p class=\"lead\">选择每日比赛，参考实时赔率，输入胜平负、总进球和半场赔率，系统用泊松模型、球队画像和多模型观点输出比分、倾向和晋级影响。</p>\n        <div class=\"actions\"><a class=\"primary\" href=\"#predict\">开始分析</a><a class=\"ghost\" href=\"https://jj.zhenzhunsp.cn/#/?tabindex=0\" target=\"_blank\" rel=\"noreferrer\">打开实时赔率</a></div>\n      </div>\n      <aside class=\"hero-card\"><span>当前主推</span><strong id=\"heroPick\">-</strong><p id=\"heroText\">-</p></aside>\n    </section>\n\n    <section id=\"odds\" class=\"panel live-panel\">\n      <div class=\"section-head\"><div><h2>实时赔率参考</h2><p>优先尝试嵌入你提供的实时赔率页面。如果第三方禁止嵌入，请新窗口打开后把赔率填入计算器。</p></div><a class=\"mini\" href=\"https://jj.zhenzhunsp.cn/#/?tabindex=0\" target=\"_blank\" rel=\"noreferrer\">新窗口打开</a></div>\n      <iframe title=\"实时赔率\" src=\"https://jj.zhenzhunsp.cn/#/?tabindex=0\" loading=\"lazy\"></iframe>\n      <div class=\"iframe-note\">如果这里空白，通常是对方网站禁止 iframe 嵌入，不影响手动录入赔率计算。</div>\n    </section>\n\n    <section id=\"predict\" class=\"layout locked\">\n      <div id=\"paywall\" class=\"paywall\"><div><b>预测功能需开通</b><span>手机号注册登录后，充值 1.99 元即可使用预测功能。</span></div><button id=\"openPaywall\">立即开通</button></div>\n      <aside class=\"side\">\n        <section class=\"panel\"><h2>每日赛程</h2><label>日期<select id=\"dateSelect\"></select></label></section>\n        <section id=\"matchList\" class=\"match-list\"></section>\n      </aside>\n      <section class=\"desk\">\n        <section class=\"match-hero panel\">\n          <p id=\"meta\" class=\"eyebrow dark\">-</p>\n          <h2 id=\"title\">-</h2>\n          <p id=\"context\">-</p>\n          <div class=\"result-strip\"><div><span>模型倾向</span><b id=\"pick\">-</b></div><div><span>预期进球</span><b id=\"xg\">-</b></div><div><span>大 2.5</span><b id=\"over25\">-</b></div></div>\n        </section>\n        <section class=\"grid two\">\n          <article class=\"panel\"><div class=\"section-head\"><h2>泊松概率</h2><p>枚举 0-6 球比分矩阵，归一化后得到胜平负和常见比分。</p></div><div class=\"prob\"><div><span>主胜</span><b id=\"pH\">-</b></div><div><span>平局</span><b id=\"pD\">-</b></div><div><span>客胜</span><b id=\"pA\">-</b></div></div><div id=\"scores\" class=\"scores\"></div></article>\n          <article class=\"panel\"><div class=\"section-head\"><h2>赔率录入</h2><p>参考中国体育彩票实时页面手动填入胜平负、大小球和半场赔率。</p></div><div class=\"odds\"><label>主胜<input id=\"oH\" type=\"number\" step=\"0.01\" min=\"1.01\"></label><label>平局<input id=\"oD\" type=\"number\" step=\"0.01\" min=\"1.01\"></label><label>客胜<input id=\"oA\" type=\"number\" step=\"0.01\" min=\"1.01\"></label><label>大2.5<input id=\"oO\" type=\"number\" step=\"0.01\" min=\"1.01\"></label><label>小2.5<input id=\"oU\" type=\"number\" step=\"0.01\" min=\"1.01\"></label><label>半场平<input id=\"oHT\" type=\"number\" step=\"0.01\" min=\"1.01\"></label></div><div id=\"oddsText\" class=\"note\"></div></article>\n        </section>\n        <section id=\"strategyLab\" class=\"panel\">\n          <div class=\"section-head\"><h2>盘口 / 凯利 / 数据训练</h2><p>结合盘口赔率、凯利公式、泊松概率和本地历史样本，监控赔率变化并调整策略权重。</p></div>\n          <div class=\"lab-grid\">\n            <article class=\"lab-card\"><h3>盘口赔率</h3><div class=\"odds\"><label>让球盘<input id=\"handicapLine\" type=\"number\" step=\"0.25\" value=\"-0.5\"></label><label>让球主队<input id=\"handicapHome\" type=\"number\" step=\"0.01\" min=\"1.01\" value=\"1.90\"></label><label>让球客队<input id=\"handicapAway\" type=\"number\" step=\"0.01\" min=\"1.01\" value=\"1.90\"></label></div><div id=\"handicapText\" class=\"note\"></div></article>\n            <article class=\"lab-card\"><h3>凯利公式</h3><div id=\"kellyGrid\" class=\"kelly-grid\"></div><div class=\"note\">凯利值只用于模型比较，不构成投注建议。实际商业化需合规审查。</div></article>\n            <article class=\"lab-card\"><h3>数据收集</h3><div class=\"odds\"><label>赛果<input id=\"resultScore\" type=\"text\" placeholder=\"如 2-1\"></label><label>监控阈值<input id=\"moveThreshold\" type=\"number\" step=\"0.01\" value=\"0.08\"></label><label>监控间隔<input id=\"monitorSeconds\" type=\"number\" step=\"5\" value=\"30\"></label></div><div class=\"actions small-actions\"><button id=\"recordOdds\" type=\"button\" class=\"mini\">记录当前赔率</button><button id=\"saveResult\" type=\"button\" class=\"mini\">保存赛果</button><button id=\"toggleMonitor\" type=\"button\" class=\"mini\">开始监控</button><button id=\"exportSamples\" type=\"button\" class=\"mini\">导出样本</button><button id=\"clearSamples\" type=\"button\" class=\"mini danger\">清空</button></div><div id=\"dataStats\" class=\"note\"></div></article>\n            <article class=\"lab-card\"><h3>训练策略</h3><label>盘口权重<input id=\"wMarket\" type=\"range\" min=\"0\" max=\"100\" value=\"35\"></label><label>泊松权重<input id=\"wPoisson\" type=\"range\" min=\"0\" max=\"100\" value=\"35\"></label><label>阵容状态<input id=\"wTeam\" type=\"range\" min=\"0\" max=\"100\" value=\"30\"></label><div id=\"trainingText\" class=\"note\"></div></article>\n          </div>\n          <div id=\"oddsHistory\" class=\"history\"></div>\n        </section>        <section class=\"grid two\"><article id=\"compare\" class=\"panel\"></article><article id=\"path\" class=\"panel\"></article></section>\n        <section id=\"aiModels\" class=\"panel\"><div class=\"section-head\"><h2>AI多模型预测</h2><p>K3 本地模型已启用；千问和 DeepSeek 通过服务端代理接入，正式调用不能把 API Key 放在浏览器。</p></div><div id=\"aiGrid\" class=\"ai-grid\"></div></section>\n        <section class=\"panel\"><div class=\"section-head\"><h2>梦想单推理</h2><p>组合倾向会随赔率录入变化。此页面是分析工具，不是投注承诺。</p></div><div id=\"reason\" class=\"reason\"></div></section>\n      </section>\n    </section>\n  </main>  <dialog id=\"authDialog\" class=\"auth-dialog\">\n    <form method=\"dialog\" class=\"auth-box\">\n      <button class=\"close\" value=\"cancel\" aria-label=\"关闭\">×</button>\n      <h2>手机号注册 / 充值开通</h2>\n      <p>当前采用人工开通：用户支付 1.99 元后，把手机号和付款截图发给管理员；管理员核对到账后发放授权码。自动到账开通需要后续接入支付宝商户支付回调。</p>\n      <label>手机号<input id=\"phoneInput\" type=\"tel\" placeholder=\"请输入 11 位手机号\" /></label>\n      <div class=\"pay-card\"><span>充值金额</span><b>¥1.99</b><small>扫码付款后联系管理员人工核验</small></div>\n      <div id=\"alipayBox\" class=\"alipay-box\"><img src=\"data:image/jpeg;base64,\" alt=\"支付宝收款码\" /></div>\n      <label>授权码<input id=\"unlockCode\" type=\"text\" placeholder=\"管理员核验后发放授权码\" /></label>\n      <button id=\"activateBtn\" type=\"button\" class=\"activate\">开通预测</button>\n      <details class=\"admin-tools\">\n        <summary>管理员生成授权码</summary>\n        <label>后台口令<input id=\"adminPassword\" type=\"password\" placeholder=\"仅管理员使用\" /></label>\n        <button id=\"generateCodeBtn\" type=\"button\" class=\"mini\">生成当前手机号授权码</button>\n        <div id=\"adminCodeResult\" class=\"auth-hint\"></div>\n      </details>\n      <div id=\"authHint\" class=\"auth-hint\"></div>\n    </form>\n  </dialog>\n\n  <footer>数据为演示模型。临场首发、伤停、盘口变化和官方赛程更新会改变判断。</footer>\n  <script type=\"module\">const teams = {\n  Brazil:{zh:\"巴西\",code:\"BRA\",group:\"C\",formation:\"4-3-3\",style:\"边路爆点多，前场压迫强，定位球防守需谨慎。\",stars:[\"Vinicius Junior\",\"Rodrygo\",\"Bruno Guimaraes\"],attack:94,midfield:88,defense:84,form:84,depth:90,baseXg:2.15},\n  Haiti:{zh:\"海地\",code:\"HAI\",group:\"C\",formation:\"5-4-1\",style:\"低位防守，依赖反击和二点球，控球推进偏弱。\",stars:[\"Duckens Nazon\",\"Frantzdy Pierrot\",\"Jean-Ricner Bellegarde\"],attack:64,midfield:61,defense:59,form:62,depth:55,baseXg:.78},\n  Scotland:{zh:\"苏格兰\",code:\"SCO\",group:\"C\",formation:\"3-4-2-1\",style:\"身体对抗强，边翼卫推进明确，中路创造力依赖核心状态。\",stars:[\"Scott McTominay\",\"Andrew Robertson\",\"John McGinn\"],attack:74,midfield:78,defense:76,form:73,depth:70,baseXg:1.22},\n  Morocco:{zh:\"摩洛哥\",code:\"MAR\",group:\"C\",formation:\"4-1-4-1\",style:\"防线纪律强，边路转换快，适合打强队身后空间。\",stars:[\"Achraf Hakimi\",\"Sofyan Amrabat\",\"Youssef En-Nesyri\"],attack:78,midfield:80,defense:84,form:81,depth:76,baseXg:1.34},\n  Turkiye:{zh:\"土耳其\",code:\"TUR\",group:\"D\",formation:\"4-2-3-1\",style:\"前腰和边锋创造力强，节奏高，防守转换有波动。\",stars:[\"Hakan Calhanoglu\",\"Arda Guler\",\"Kenan Yildiz\"],attack:81,midfield:82,defense:73,form:78,depth:75,baseXg:1.48},\n  Paraguay:{zh:\"巴拉圭\",code:\"PAR\",group:\"D\",formation:\"4-4-2\",style:\"防守韧性和空中对抗好，进攻依赖定位球和二次进攻。\",stars:[\"Miguel Almiron\",\"Julio Enciso\",\"Gustavo Gomez\"],attack:73,midfield:72,defense:78,form:74,depth:70,baseXg:1.12},\n  USA:{zh:\"美国\",code:\"USA\",group:\"D\",formation:\"4-3-3\",style:\"跑动覆盖大，边路速度明显，主场环境提升压迫强度。\",stars:[\"Christian Pulisic\",\"Weston McKennie\",\"Tyler Adams\"],attack:80,midfield:79,defense:77,form:80,depth:78,baseXg:1.52},\n  Australia:{zh:\"澳大利亚\",code:\"AUS\",group:\"D\",formation:\"4-4-1-1\",style:\"防守组织稳定，身体对抗强，阵地战破密集效率一般。\",stars:[\"Jackson Irvine\",\"Harry Souttar\",\"Mathew Ryan\"],attack:69,midfield:71,defense:75,form:72,depth:68,baseXg:1.03},\n  Germany:{zh:\"德国\",code:\"GER\",group:\"E\",formation:\"4-2-3-1\",style:\"中前场技术密度高，阵地战强，防线身后空间需控制。\",stars:[\"Jamal Musiala\",\"Florian Wirtz\",\"Joshua Kimmich\"],attack:88,midfield:90,defense:80,form:83,depth:86,baseXg:1.82},\n  CIV:{zh:\"科特迪瓦\",code:\"CIV\",group:\"E\",formation:\"4-3-3\",style:\"个人冲击力强，转换速度快，防线协同影响上限。\",stars:[\"Sebastien Haller\",\"Franck Kessie\",\"Simon Adingra\"],attack:77,midfield:76,defense:72,form:79,depth:73,baseXg:1.28},\n  Netherlands:{zh:\"荷兰\",code:\"NED\",group:\"F\",formation:\"3-4-2-1\",style:\"三中卫出球稳定，定位球强，前场终结效率决定上限。\",stars:[\"Virgil van Dijk\",\"Frenkie de Jong\",\"Xavi Simons\"],attack:84,midfield:84,defense:87,form:82,depth:82,baseXg:1.62},\n  Sweden:{zh:\"瑞典\",code:\"SWE\",group:\"F\",formation:\"4-4-2\",style:\"前锋支点明确，长传和边路传中直接，防线移动速度是风险点。\",stars:[\"Alexander Isak\",\"Dejan Kulusevski\",\"Viktor Gyokeres\"],attack:82,midfield:76,defense:74,form:77,depth:74,baseXg:1.42}\n};\n\nlet matches = [\n  {id:\"bra-hai\",date:\"2026-06-19\",time:\"待确认\",group:\"C\",venue:\"Philadelphia Stadium\",home:\"Brazil\",away:\"Haiti\",stakes:\"巴西争取提前锁定出线主动权；海地需要控制净胜球，第三名排名也会受影响。\",odds:{h:1.12,d:6.8,a:18,o:1.58,u:2.15,ht:2.75}},\n  {id:\"sco-mar\",date:\"2026-06-19\",time:\"待确认\",group:\"C\",venue:\"Boston Stadium\",home:\"Scotland\",away:\"Morocco\",stakes:\"C组第二名关键战，胜者大概率占据直接晋级位置，败者可能被迫计算第三名积分。\",odds:{h:3.05,d:3.05,a:2.25,o:2.08,u:1.62,ht:1.95}},\n  {id:\"tur-par\",date:\"2026-06-19\",time:\"待确认\",group:\"D\",venue:\"San Francisco Bay Area Stadium\",home:\"Turkiye\",away:\"Paraguay\",stakes:\"D组中游对冲战，平局会让最后一轮压力上升，胜者接近前二。\",odds:{h:2.18,d:3.1,a:3.15,o:1.92,u:1.76,ht:2.02}},\n  {id:\"usa-aus\",date:\"2026-06-19\",time:\"待确认\",group:\"D\",venue:\"Seattle Stadium\",home:\"USA\",away:\"Australia\",stakes:\"美国主场优势明显，若取胜将大幅提升小组前二概率；澳大利亚需要降低比赛回合数。\",odds:{h:1.82,d:3.35,a:4.05,o:1.88,u:1.82,ht:2.08}},\n  {id:\"ger-civ\",date:\"2026-06-20\",time:\"待确认\",group:\"E\",venue:\"Toronto Stadium\",home:\"Germany\",away:\"CIV\",stakes:\"德国控球优势明显，但科特迪瓦转换速度会测试德国防线身后保护。\",odds:{h:1.62,d:3.65,a:5.1,o:1.72,u:1.98,ht:2.22}},\n  {id:\"ned-swe\",date:\"2026-06-20\",time:\"待确认\",group:\"F\",venue:\"Houston Stadium\",home:\"Netherlands\",away:\"Sweden\",stakes:\"荷兰控场与瑞典双前锋冲击的对比明显，定位球可能改变胜负概率。\",odds:{h:1.88,d:3.25,a:3.85,o:1.95,u:1.75,ht:2.05}}\n];\n\nlet state = {date: matches[0].date, id: matches[0].id};\nlet scheduleMeta = {source:\"本地演示赛程\", updatedAt:null, fallback:true};\nconst $ = (selector) => document.querySelector(selector);\nconst pct = (value) => `${(value * 100).toFixed(1)}%`;\nconst clamp = (value, min, max) => Math.max(min, Math.min(max, value));\n\nfunction factorial(n){let result = 1; for(let i = 2; i <= n; i += 1) result *= i; return result;}\nfunction poisson(lambda, goals){return Math.exp(-lambda) * Math.pow(lambda, goals) / factorial(goals);}\nfunction currentMatch(){return matches.find((match) => match.id === state.id) || matches[0];}\nfunction expectedGoals(match){const h = teams[match.home], a = teams[match.away]; const edge = match.home === \"USA\" ? .18 : .08; return {h: clamp(h.baseXg + (h.attack - a.defense) / 52 + (h.form - a.form) / 95 + edge, .25, 3.6), a: clamp(a.baseXg + (a.attack - h.defense) / 55 + (a.form - h.form) / 100, .2, 3.2)};}\nfunction model(match){const xg = expectedGoals(match); const scores = []; let h = 0, d = 0, a = 0, over = 0, bts = 0; for(let home = 0; home <= 6; home += 1){for(let away = 0; away <= 6; away += 1){const p = poisson(xg.h, home) * poisson(xg.a, away); scores.push({score:`${home}-${away}`, p}); if(home > away) h += p; else if(home === away) d += p; else a += p; if(home + away > 2.5) over += p; if(home && away) bts += p;}} const covered = scores.reduce((sum, item) => sum + item.p, 0); return {xg, h:h/covered, d:d/covered, a:a/covered, over:over/covered, bts:bts/covered, scores:scores.sort((x,y)=>y.p-x.p).slice(0,5)};}\nfunction readOdds(){return {h:+$(\"#oH\").value,d:+$(\"#oD\").value,a:+$(\"#oA\").value,o:+$(\"#oO\").value,u:+$(\"#oU\").value,ht:+$(\"#oHT\").value};}\nfunction implied(odds){const raw = {h:1/odds.h,d:1/odds.d,a:1/odds.a}; const total = raw.h + raw.d + raw.a; return {h:raw.h/total,d:raw.d/total,a:raw.a/total,margin:total-1};}\nfunction normalizeRemoteSchedule(payload){const rows = Array.isArray(payload) ? payload : payload.matches; if(!Array.isArray(rows)) return []; return rows.map((item, index)=>{const homeKey = item.homeKey || item.home || item.homeTeam || `RemoteHome${index}`; const awayKey = item.awayKey || item.away || item.awayTeam || `RemoteAway${index}`; if(!teams[homeKey]) teams[homeKey] = {zh:item.homeName || item.home || homeKey,code:String(homeKey).slice(0,3).toUpperCase(),group:item.group || \"竞彩\",formation:item.homeFormation || \"待确认\",style:item.homeStyle || \"赛前阵容、伤停和风格需结合实时情报确认。\",stars:item.homeStars || [\"首发待确认\"],attack:item.homeAttack || 72,midfield:item.homeMidfield || 72,defense:item.homeDefense || 72,form:item.homeForm || 72,depth:item.homeDepth || 70,baseXg:item.homeXg || 1.25}; if(!teams[awayKey]) teams[awayKey] = {zh:item.awayName || item.away || awayKey,code:String(awayKey).slice(0,3).toUpperCase(),group:item.group || \"竞彩\",formation:item.awayFormation || \"待确认\",style:item.awayStyle || \"赛前阵容、伤停和风格需结合实时情报确认。\",stars:item.awayStars || [\"首发待确认\"],attack:item.awayAttack || 72,midfield:item.awayMidfield || 72,defense:item.awayDefense || 72,form:item.awayForm || 72,depth:item.awayDepth || 70,baseXg:item.awayXg || 1.2}; return {id:item.id || `${homeKey}-${awayKey}-${item.date || \"\"}`.toLowerCase().replace(/[^a-z0-9-]/g,\"-\"),date:item.date || new Date().toISOString().slice(0,10),time:item.time || \"待确认\",group:item.group || \"竞彩\",venue:item.venue || item.league || \"体彩开放赛事\",home:homeKey,away:awayKey,stakes:item.stakes || \"自动更新赛程，阵容与盘口需临场复核。\",odds:{h:+(item.odds?.h || item.h || item.win || 2.1),d:+(item.odds?.d || item.d || item.draw || 3.1),a:+(item.odds?.a || item.a || item.loss || 3.2),o:+(item.odds?.o || item.o || item.over || 1.9),u:+(item.odds?.u || item.u || item.under || 1.85),ht:+(item.odds?.ht || item.ht || item.halfDraw || 2.05)}};}).filter((item)=>item.home && item.away);}\nasync function loadSchedule(){try{const response = await fetch(\"/api/schedule\",{cache:\"no-store\"}); if(!response.ok) throw new Error(`HTTP ${response.status}`); const payload = await response.json(); const remote = normalizeRemoteSchedule(payload); scheduleMeta = {source:payload.source || \"远程赛程源\", updatedAt:payload.updatedAt || new Date().toISOString(), fallback:!remote.length, message:payload.message || \"\"}; if(remote.length){matches = remote; state.date = matches[0].date; state.id = matches[0].id; render();}}catch(error){scheduleMeta = {...scheduleMeta, fallback:true, message:`实时赛程暂未更新：${error.message}`};}}\n\nfunction renderDates(){const dates = [...new Set(matches.map((match)=>match.date))]; $(\"#dateSelect\").innerHTML = dates.map((date)=>`<option value=\"${date}\">${date}</option>`).join(\"\"); $(\"#dateSelect\").value = state.date;}\nfunction renderMatchList(){const list = matches.filter((match)=>match.date === state.date); if(!list.length){$(\"#matchList\").innerHTML = `<div class=\"note\">今日暂无可用赛程。${scheduleMeta.message || \"\"}</div>`; return;} if(!list.some((match)=>match.id === state.id)) state.id = list[0].id; const status = `<div class=\"schedule-status ${scheduleMeta.fallback?\"warn\":\"ok\"}\">赛程源：${scheduleMeta.source}${scheduleMeta.updatedAt ? ` · ${new Date(scheduleMeta.updatedAt).toLocaleString()}` : \"\"}${scheduleMeta.message ? `<br>${scheduleMeta.message}` : \"\"}</div>`; $(\"#matchList\").innerHTML = status + list.map((match)=>`<button class=\"match ${match.id===state.id?\"active\":\"\"}\" data-id=\"${match.id}\"><strong>${teams[match.home].zh} vs ${teams[match.away].zh}</strong><span>${match.group}组 · ${match.venue}</span><span>${match.stakes}</span></button>`).join(\"\");}\nfunction setOdds(match){$(\"#oH\").value=match.odds.h;$(\"#oD\").value=match.odds.d;$(\"#oA\").value=match.odds.a;$(\"#oO\").value=match.odds.o;$(\"#oU\").value=match.odds.u;$(\"#oHT\").value=match.odds.ht;}\nfunction renderOddsText(md){const odds = readOdds(); if([odds.h, odds.d, odds.a].some((value)=>!value || value <= 1)){ $(\"#oddsText\").textContent = \"请输入有效赔率。\"; return;} const market = implied(odds); const gap = [[\"主胜\", md.h-market.h],[\"平局\", md.d-market.d],[\"客胜\", md.a-market.a]].sort((x,y)=>y[1]-x[1]); const overMarket = odds.o && odds.u ? (1/odds.o)/(1/odds.o+1/odds.u) : 0; $(\"#oddsText\").innerHTML = `赔率隐含：主胜 ${pct(market.h)}、平局 ${pct(market.d)}、客胜 ${pct(market.a)}；水位约 ${(market.margin*100).toFixed(1)}%。<br>模型差最大：${gap[0][0]} ${gap[0][1]>=0?\"+\":\"\"}${(gap[0][1]*100).toFixed(1)} 个百分点。${overMarket ? `<br>大2.5 隐含 ${pct(overMarket)}，泊松模型 ${pct(md.over)}。` : \"\"}`;}\nfunction statBars(team){const labels = {attack:\"进攻\", midfield:\"中场\", defense:\"防守\", form:\"状态\", depth:\"深度\"}; return Object.keys(labels).map((key)=>`<div class=\"bar\"><span>${labels[key]}</span><span class=\"track\"><span class=\"fill\" style=\"width:${team[key]}%\"></span></span><span>${team[key]}</span></div>`).join(\"\");}\nfunction renderAIModels(home, away, md, choices){const strength = (home.attack+home.midfield+home.defense+home.form+away.attack+away.midfield+away.defense+away.form)/8; const caution = md.d > .27 ? \"平局权重偏高，建议复核半场和小球赔率。\" : \"胜负方向较清晰，重点复核临场首发。\"; const cards = [[\"K3本地泊松\",\"已启用\",`${choices[0].label} ${pct(choices[0].value)}`,`基于预期进球 ${md.xg.h.toFixed(2)}-${md.xg.a.toFixed(2)}、比分矩阵和赔率差值生成。`],[\"Qwen 千问\",\"连接中\",\"等待服务端返回\",\"用于中文赛事情报、伤停摘要、球队新闻结构化。\"],[\"DeepSeek\",\"连接中\",\"等待服务端返回\",\"用于赔率异动、凯利风险和策略解释交叉检查。\"]]; return cards.map((card)=>`<div class=\"ai-card ${card[1]!==\"已启用\"?\"pending\":\"\"}\" data-ai-card=\"${card[0]}\"><h3>${card[0]}<em>${card[1]}</em></h3><strong>${card[2]}</strong><p>${card[3]}</p><p>${caution} 综合强度指数 ${strength.toFixed(1)}。</p></div>`).join(\"\");}\nasync function refreshAIAnalysis(match, home, away, md, choices){try{const response=await fetch(\"/api/ai-analysis\",{method:\"POST\",headers:{\"content-type\":\"application/json\"},body:JSON.stringify({match:{id:match.id,date:match.date,group:match.group,venue:match.venue,stakes:match.stakes},home:{name:home.zh,formation:home.formation,style:home.style,stars:home.stars},away:{name:away.zh,formation:away.formation,style:away.style,stars:away.stars},model:{pick:choices[0].label,probability:choices[0].value,xg:md.xg,over25:md.over,bts:md.bts,topScores:md.scores},odds:readOdds(),samples:getSamples().filter(s=>s.matchId===match.id).slice(-8)})});const data=await response.json();for(const item of data.results||[]){const card=document.querySelector(`[data-ai-card=\"${item.provider}\"]`);if(card){card.classList.toggle(\"pending\",!item.ok);card.innerHTML=`<h3>${item.provider}<em>${item.ok?\"已接入\":\"未可用\"}</em></h3><strong>${item.pick||\"暂无结论\"}</strong><p>${item.analysis||item.error||\"服务端未返回内容。\"}</p>`;}}}catch(error){for(const provider of [\"Qwen 千问\",\"DeepSeek\"]){const card=document.querySelector(`[data-ai-card=\"${provider}\"]`);if(card){card.classList.add(\"pending\");card.innerHTML=`<h3>${provider}<em>连接失败</em></h3><strong>服务端不可用</strong><p>${error.message}</p>`;}}}}\n\nlet monitorTimer = null;\nfunction parseResultScore(text){const m=String(text||\"\").trim().match(/^(\\d+)\\s*[-:]\\s*(\\d+)$/); return m?{home:+m[1],away:+m[2]}:null;}\nfunction outcomeFromScore(score){if(!score)return null; return score.home>score.away?\"h\":score.home===score.away?\"d\":\"a\";}\nfunction trainFromSamples(){const done=getSamples().filter(s=>s.result); if(!done.length)return null; let marketHit=0,poissonHit=0; for(const s of done){const marketPick=Object.entries(s.odds).filter(([k])=>[\"h\",\"d\",\"a\"].includes(k)).sort((a,b)=>a[1]-b[1])[0]?.[0]; if(marketPick===s.result)marketHit+=1; if(s.modelPick===s.result)poissonHit+=1;} const marketRate=marketHit/done.length, poissonRate=poissonHit/done.length; const market=Math.round(20+marketRate*45); const poisson=Math.round(20+poissonRate*45); const team=Math.max(10,100-market-poisson); return {count:done.length,marketRate,poissonRate,weights:{market,poisson,team}};}\nfunction applyTrainedWeights(){const trained=trainFromSamples(); if(!trained)return; $(\"#wMarket\").value=trained.weights.market; $(\"#wPoisson\").value=trained.weights.poisson; $(\"#wTeam\").value=trained.weights.team;}\nfunction saveMatchResult(){const score=parseResultScore($(\"#resultScore\")?.value); const result=outcomeFromScore(score); if(!result){alert(\"请输入正确赛果，例如 2-1\"); return;} const match=currentMatch(); const samples=getSamples(); const last=[...samples].reverse().find(s=>s.matchId===match.id); if(last){last.score=score; last.result=result;} else {samples.push({time:Date.now(),matchId:match.id,odds:readOdds(),result,score});} setSamples(samples); applyTrainedWeights(); renderMain();}\nfunction toggleMonitor(){const btn=$(\"#toggleMonitor\"); if(monitorTimer){clearInterval(monitorTimer); monitorTimer=null; if(btn)btn.textContent=\"开始监控\"; return;} recordCurrentOdds(); const seconds=Math.max(5,+$(\"#monitorSeconds\")?.value||30); monitorTimer=setInterval(()=>{recordCurrentOdds(true);},seconds*1000); if(btn)btn.textContent=\"停止监控\";}\nfunction kellyFraction(probability, decimalOdds){const b=decimalOdds-1; if(!b || b<=0) return 0; return Math.max(0,(b*probability-(1-probability))/b);}\nfunction getSamples(){try{return JSON.parse(localStorage.getItem(\"k3OddsSamples\")||\"[]\");}catch{return [];}}\nfunction setSamples(samples){localStorage.setItem(\"k3OddsSamples\",JSON.stringify(samples.slice(-300)));}\nfunction readWeights(){return {market:+$(\"#wMarket\")?.value||35, poisson:+$(\"#wPoisson\")?.value||35, team:+$(\"#wTeam\")?.value||30};}\nfunction renderAdvancedAnalytics(match, home, away, md, choices){\n  const odds = readOdds();\n  const hLine = +$(\"#handicapLine\")?.value || 0;\n  const hHome = +$(\"#handicapHome\")?.value || 1.9;\n  const hAway = +$(\"#handicapAway\")?.value || 1.9;\n  const fav = choices[0];\n  const handicapLean = hLine < 0 ? `${home.zh}让 ${Math.abs(hLine)}` : hLine > 0 ? `${away.zh}让 ${Math.abs(hLine)}` : \"平手盘\";\n  const handicapImpliedHome = (1/hHome)/((1/hHome)+(1/hAway));\n  $(\"#handicapText\").innerHTML = `${handicapLean}；盘口隐含主队方向 ${pct(handicapImpliedHome)}，泊松主胜 ${pct(md.h)}。`;\n  const kellyItems = [[`${home.zh}胜`,md.h,odds.h],[\"平局\",md.d,odds.d],[`${away.zh}胜`,md.a,odds.a]];\n  $(\"#kellyGrid\").innerHTML = kellyItems.map(([label,p,o])=>`<div class=\"kelly-cell\"><span>${label}</span><b>${pct(kellyFraction(p,o))}</b><span>赔率 ${o || \"-\"}</span></div>`).join(\"\");\n  const samples = getSamples();\n  const matchSamples = samples.filter(s=>s.matchId===match.id);\n  const last = matchSamples.at(-1);\n  const move = last ? `较上次：主胜 ${((odds.h-last.odds.h)||0).toFixed(2)}，平局 ${((odds.d-last.odds.d)||0).toFixed(2)}，客胜 ${((odds.a-last.odds.a)||0).toFixed(2)}` : \"暂无上一条样本\";\n  const trained=trainFromSamples(); const threshold=+$(\"#moveThreshold\")?.value||0.08; const isAlert=last && Math.max(Math.abs(odds.h-last.odds.h||0),Math.abs(odds.d-last.odds.d||0),Math.abs(odds.a-last.odds.a||0))>=threshold; $(\"#dataStats\").innerHTML = `总样本 ${samples.length} 条；本场 ${matchSamples.length} 条。${move}${trained?`<br>训练样本 ${trained.count} 条；盘口命中 ${(trained.marketRate*100).toFixed(1)}%，泊松命中 ${(trained.poissonRate*100).toFixed(1)}%。建议权重：盘口 ${trained.weights.market} / 泊松 ${trained.weights.poisson} / 阵容 ${trained.weights.team}`:\"\"}${isAlert?`<div class=\"monitor-alert\">赔率变化超过阈值 ${threshold.toFixed(2)}，建议复核盘口。</div>`:\"\"}`;\n  const weights = readWeights();\n  const total = weights.market + weights.poisson + weights.team;\n  const selectedOdd = fav.label === `${home.zh}胜` ? odds.h : fav.label === \"平局\" ? odds.d : odds.a;\n  const marketSignal = 1 / Math.max(1.01, selectedOdd || 2);\n  const poissonSignal = fav.value;\n  const teamSignal = (home.attack+home.midfield+home.defense+away.attack+away.midfield+away.defense)/600;\n  const score = ((weights.market*marketSignal)+(weights.poisson*poissonSignal)+(weights.team*teamSignal))/total;\n  $(\"#trainingText\").innerHTML = `策略评分 ${(score*100).toFixed(1)}；当前建议：${score>.48?\"可进入重点观察池\":\"等待赔率或阵容确认\"}。持续记录样本后，可用于回测权重。`;\n  $(\"#oddsHistory\").innerHTML = matchSamples.slice(-6).reverse().map(s=>`<div class=\"history-row\"><b>${new Date(s.time).toLocaleTimeString()}</b><span>主 ${s.odds.h}</span><span>平 ${s.odds.d}</span><span>客 ${s.odds.a}</span></div>`).join(\"\") || '<div class=\"note\">暂无本场历史样本，点击“记录当前赔率”开始收集。</div>';\n}\nfunction recordCurrentOdds(silent=false){const match=currentMatch(); const md=model(match); const choices=[{key:\"h\",value:md.h},{key:\"d\",value:md.d},{key:\"a\",value:md.a}].sort((a,b)=>b.value-a.value); const samples=getSamples(); const current={time:Date.now(),matchId:match.id,odds:readOdds(),modelPick:choices[0].key,handicap:{line:+$(\"#handicapLine\").value,home:+$(\"#handicapHome\").value,away:+$(\"#handicapAway\").value}}; samples.push(current); setSamples(samples); if(!silent)renderMain(); else renderMain();}\nfunction exportSamples(){const blob=new Blob([JSON.stringify(getSamples(),null,2)],{type:\"application/json\"}); const url=URL.createObjectURL(blob); const a=document.createElement(\"a\"); a.href=url; a.download=\"k3-odds-samples.json\"; a.click(); URL.revokeObjectURL(url);}\nfunction clearSamples(){setSamples([]); renderMain();}\nfunction renderMain(){const match = currentMatch(); const home = teams[match.home], away = teams[match.away], md = model(match); const choices = [{label:`${home.zh}胜`,value:md.h},{label:\"平局\",value:md.d},{label:`${away.zh}胜`,value:md.a}].sort((x,y)=>y.value-x.value); $(\"#heroPick\").textContent = `${choices[0].label} ${pct(choices[0].value)}`; $(\"#heroText\").textContent = `${home.zh} vs ${away.zh}，最高概率比分 ${md.scores[0].score}。`; $(\"#meta\").textContent = `${match.date} · ${match.group}组 · ${match.venue} · ${match.time}`; $(\"#title\").textContent = `${home.zh} vs ${away.zh}`; $(\"#context\").textContent = match.stakes; $(\"#pick\").textContent = `${choices[0].label} ${pct(choices[0].value)}`; $(\"#xg\").textContent = `${md.xg.h.toFixed(2)} - ${md.xg.a.toFixed(2)}`; $(\"#over25\").textContent = pct(md.over); $(\"#pH\").textContent = pct(md.h); $(\"#pD\").textContent = pct(md.d); $(\"#pA\").textContent = pct(md.a); $(\"#scores\").innerHTML = md.scores.map((item)=>`<div class=\"score\"><b>${item.score}</b><span>${pct(item.p)}</span></div>`).join(\"\"); setOdds(match); renderOddsText(md); $(\"#compare\").innerHTML = `<div class=\"section-head\"><h2>阵容与风格</h2><p>阵型和核心球员为赛前分析口径，正式首发需赛前确认。</p></div><div class=\"compare\">${[home,away].map((team)=>`<div class=\"team\"><header><div><h3>${team.zh}</h3><p>${team.formation} · ${team.style}</p></div><div class=\"badge\">${team.code}</div></header>${statBars(team)}<ul class=\"bullets\">${team.stars.map((star)=>`<li>${star}</li>`).join(\"\")}</ul></div>`).join(\"\")}</div>`; $(\"#path\").innerHTML = `<div class=\"section-head\"><h2>晋级路径</h2><p>48队分12组，每组前二和8个最佳第三进入32强。</p></div><div class=\"advance\"><div class=\"metric\"><span>本场关键</span><strong>${choices[0].label}更占优</strong></div><div class=\"metric\"><span>小组影响</span><strong>${md.d>.27?\"平局概率偏高，第三名积分和净胜球权重上升。\":\"胜负倾向较清晰，胜者更接近小组前二。\"}</strong></div><div class=\"metric\"><span>32强推理</span><strong>${match.group}组前二进入固定32强路径；第三名对手取决于8个最佳第三组合。</strong></div><div class=\"metric\"><span>赛程风险</span><strong>短间隔比赛下，阵容深度和轮换能力会提高权重。</strong></div></div>`; $(\"#aiGrid\").innerHTML = renderAIModels(home, away, md, choices); refreshAIAnalysis(match, home, away, md, choices); renderAdvancedAnalytics(match, home, away, md, choices); $(\"#reason\").innerHTML = [[\"胜负\",`首选 ${choices[0].label}。预期进球 ${home.zh} ${md.xg.h.toFixed(2)}，${away.zh} ${md.xg.a.toFixed(2)}。`],[\"比分\",`最高概率比分 ${md.scores[0].score}，其次 ${md.scores.slice(1,3).map((item)=>item.score).join(\"、\")}。`],[\"半场\",`半场进球按全场约45%估算，半场平局通常高于全场平局，需单独校验半场赔率。`],[\"梦想单\",`大2.5概率 ${pct(md.over)}，双方进球概率 ${pct(md.bts)}；赔率差异较大时优先复查实时盘口。`]].map((item)=>`<div class=\"reason-card\"><h3>${item[0]}</h3><p>${item[1]}</p></div>`).join(\"\");}\nfunction render(){renderDates(); renderMatchList(); renderMain(); refreshAccess();}\n\nfunction isActivated(){return localStorage.getItem(\"k3Activated\") === \"1\";}\nfunction refreshAccess(){const predict = $(\"#predict\"); const btn = $(\"#accountBtn\"); if(!predict || !btn) return; predict.classList.toggle(\"locked\", !isActivated()); btn.textContent = isActivated() ? \"已开通\" : \"登录/充值\";}\nfunction openAuth(){const dialog = $(\"#authDialog\"); if(dialog) dialog.showModal();}\n\n$(\"#dateSelect\").addEventListener(\"change\", (event)=>{state.date = event.target.value; state.id = matches.find((match)=>match.date === state.date).id; render();});\n$(\"#matchList\").addEventListener(\"click\", (event)=>{const button = event.target.closest(\".match\"); if(button){state.id = button.dataset.id; render();}});\n[\"#oH\",\"#oD\",\"#oA\",\"#oO\",\"#oU\",\"#oHT\",\"#handicapLine\",\"#handicapHome\",\"#handicapAway\",\"#wMarket\",\"#wPoisson\",\"#wTeam\"].forEach((selector)=>$(selector)?.addEventListener(\"input\",()=>renderMain()));\n$(\"#skipIntro\").addEventListener(\"click\",()=>$(\"#intro\").classList.add(\"hide\"));\nsetTimeout(()=>$(\"#intro\").classList.add(\"hide\"),3800);\n$(\"#accountBtn\").addEventListener(\"click\", openAuth);\n$(\"#openPaywall\").addEventListener(\"click\", openAuth);\n$(\"#activateBtn\").addEventListener(\"click\", async ()=>{const phone = $(\"#phoneInput\").value.trim(); const code = $(\"#unlockCode\").value.trim(); const hint = $(\"#authHint\"); if(!/^1\\d{10}$/.test(phone)){hint.className = \"auth-hint\"; hint.textContent = \"请输入有效的 11 位手机号。\"; return;} if(!code){hint.className = \"auth-hint\"; hint.textContent = \"请输入管理员发放的授权码。\"; return;} try{hint.className = \"auth-hint\"; hint.textContent = \"正在验证授权码...\"; const response = await fetch(\"/api/verify-activation\",{method:\"POST\",headers:{\"content-type\":\"application/json\"},body:JSON.stringify({phone,code})}); const data = await response.json(); if(!response.ok || !data.ok){hint.className = \"auth-hint\"; hint.textContent = data.error || \"授权码无效。\"; return;} localStorage.setItem(\"k3Phone\", phone); localStorage.setItem(\"k3Activated\", \"1\"); localStorage.setItem(\"k3ActivatedAt\", new Date().toISOString()); hint.className = \"auth-hint ok\"; hint.textContent = \"已开通当前浏览器的预测功能。\"; refreshAccess(); setTimeout(()=>$(\"#authDialog\").close(),650);}catch(error){hint.className = \"auth-hint\"; hint.textContent = `验证失败：${error.message}`;}});\n$(\"#generateCodeBtn\")?.addEventListener(\"click\", async ()=>{const phone = $(\"#phoneInput\").value.trim(); const password = $(\"#adminPassword\").value; const result = $(\"#adminCodeResult\"); if(!/^1\\d{10}$/.test(phone)){result.className = \"auth-hint\"; result.textContent = \"先输入用户手机号。\"; return;} if(!password){result.className = \"auth-hint\"; result.textContent = \"请输入后台口令。\"; return;} try{result.className = \"auth-hint\"; result.textContent = \"正在生成...\"; const response = await fetch(\"/api/admin-code\",{method:\"POST\",headers:{\"content-type\":\"application/json\"},body:JSON.stringify({phone,password})}); const data = await response.json(); if(!response.ok || !data.ok){result.className = \"auth-hint\"; result.textContent = data.error || \"生成失败。\"; return;} result.className = \"auth-hint ok\"; result.textContent = `授权码：${data.code}`; $(\"#unlockCode\").value = data.code;}catch(error){result.className = \"auth-hint\"; result.textContent = `生成失败：${error.message}`;}});\n\nrender();\nloadSchedule();\nsetInterval(loadSchedule, 30 * 60 * 1000);\n$(\"#recordOdds\")?.addEventListener(\"click\",recordCurrentOdds);\n$(\"#exportSamples\")?.addEventListener(\"click\",exportSamples);\n$(\"#clearSamples\")?.addEventListener(\"click\",clearSamples);\n$(\"#saveResult\")?.addEventListener(\"click\",saveMatchResult);\n$(\"#toggleMonitor\")?.addEventListener(\"click\",toggleMonitor);\n</script>\n</body>\n</html>\n";

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "content-type": "application/json; charset=utf-8" }
  });
}

function buildPrompt(payload) {
  return [
    "You are a football pre-match analysis assistant. Use market odds, Kelly indicators, Poisson probabilities, squad/style context, and historical samples to produce a concise prediction.",
    "Return strict JSON only with fields pick and analysis. Do not include betting guarantees or financial promises.",
    JSON.stringify(payload)
  ].join("\\n");
}

async function sha256Text(text) {
  const bytes = new TextEncoder().encode(text);
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return Array.from(new Uint8Array(digest)).map((b) => b.toString(16).padStart(2, "0")).join("");
}

async function activationCode(phone, secret) {
  const hash = await sha256Text(String(phone).trim() + ":" + secret);
  return hash.slice(0, 8).toUpperCase();
}

function validPhone(phone) {
  return /^1\d{10}$/.test(String(phone || "").trim());
}

async function loadConfiguredSchedule(env) {
  if (!env.SCHEDULE_API_URL) {
    return {
      source: "local-fallback",
      updatedAt: new Date().toISOString(),
      matches: [],
      message: "SCHEDULE_API_URL is not configured. Showing local fallback schedule."
    };
  }

  const res = await fetch(env.SCHEDULE_API_URL, {
    headers: env.SCHEDULE_API_TOKEN ? { authorization: "Bearer " + env.SCHEDULE_API_TOKEN } : undefined
  });

  if (!res.ok) {
    return {
      source: env.SCHEDULE_API_URL,
      updatedAt: new Date().toISOString(),
      matches: [],
      message: "Schedule source returned HTTP " + res.status
    };
  }

  const data = await res.json();
  return {
    source: data.source || env.SCHEDULE_API_URL,
    updatedAt: data.updatedAt || new Date().toISOString(),
    matches: Array.isArray(data) ? data : data.matches || [],
    message: data.message || ""
  };
}

async function callChat(provider, apiKey, endpoint, model, payload) {
  if (!apiKey) return { provider, ok: false, error: "API key is not configured" };

  const res = await fetch(endpoint, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: "Bearer " + apiKey
    },
    body: JSON.stringify({
      model,
      messages: [{ role: "user", content: buildPrompt(payload) }],
      temperature: 0.2
    })
  });

  if (!res.ok) return { provider, ok: false, error: "HTTP " + res.status };

  const data = await res.json();
  const text = data.choices && data.choices[0] && data.choices[0].message
    ? data.choices[0].message.content || ""
    : "";

  try {
    return { provider, ok: true, ...JSON.parse(text) };
  } catch {
    return { provider, ok: true, pick: "Model analysis", analysis: text.slice(0, 500) };
  }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.pathname === "/health") return new Response("ok");

    if (url.pathname === "/api/schedule") {
      try {
        return json(await loadConfiguredSchedule(env));
      } catch (error) {
        return json({
          source: "schedule-error",
          updatedAt: new Date().toISOString(),
          matches: [],
          message: error.message || "Schedule update failed"
        });
      }
    }

    if (url.pathname === "/api/admin-code" && request.method === "POST") {
      const body = await request.json();
      if (!validPhone(body.phone)) return json({ ok: false, error: "Invalid phone number" }, 400);
      if (!env.ADMIN_PASSWORD || !env.ACTIVATION_SECRET) {
        return json({ ok: false, error: "Admin activation is not configured" }, 500);
      }
      if (body.password !== env.ADMIN_PASSWORD) {
        return json({ ok: false, error: "Admin password is incorrect" }, 403);
      }
      return json({ ok: true, phone: body.phone, code: await activationCode(body.phone, env.ACTIVATION_SECRET) });
    }

    if (url.pathname === "/api/verify-activation" && request.method === "POST") {
      const body = await request.json();
      if (!validPhone(body.phone)) return json({ ok: false, error: "Invalid phone number" }, 400);
      if (!env.ACTIVATION_SECRET) {
        return json({ ok: false, error: "Activation is not configured" }, 500);
      }
      const expected = await activationCode(body.phone, env.ACTIVATION_SECRET);
      if (String(body.code || "").trim().toUpperCase() !== expected) {
        return json({ ok: false, error: "授权码无效或手机号不匹配" }, 403);
      }
      return json({ ok: true, phone: body.phone });
    }

    if (url.pathname === "/api/ai-analysis" && request.method === "POST") {
      try {
        const payload = await request.json();
        const results = await Promise.all([
          callChat("Qwen", env.QWEN_API_KEY, "https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions", "qwen-plus", payload),
          callChat("DeepSeek", env.DEEPSEEK_API_KEY, "https://api.deepseek.com/chat/completions", "deepseek-chat", payload)
        ]);
        return json({ results });
      } catch (error) {
        return json({ error: error.message || "AI analysis failed" }, 500);
      }
    }

    return new Response(html, {
      headers: { "content-type": "text/html; charset=utf-8" }
    });
  }
};
